import sys
# -*- coding: utf-8 -*- import os, subprocess, json, whisper, numpy as np import soundfile as sf  FFMPEG_BIN = r"C:\Users\Administrator\miniconda3\envs\blackwell_env\Lib\site-packages\static_ffmpeg\bin\win32\ffmpeg.exe" os.environ["PATH"] = os.path.dirname(FFMPEG_BIN) + os.pathsep + os.environ["PATH"]  def denoise_and_test_seed():     role_lib_path = r"E:\VideoTranslator_Project\temp_factory\v9_role_library.json"     with open(role_lib_path, "r") as f: role_lib = json.load(f)          old_seed = role_lib['SPEAKER_00']['wav']     denoised_seed = r"E:\VideoTranslator_Project\temp_factory\DENOISED_SPK00_SEED.wav"          print(f"\n[Denoise] 正在对 SPEAKER_00 种子执行【工业级 FFT 降噪】...")          # 使用 afftdn 执行高保真降噪     # nf=-25: 降噪门限设为 -25dB     cmd_denoise = [         FFMPEG_BIN, "-y", "-i", old_seed,         "-af", "afftdn=nf=-25,highpass=f=100,lowpass=f=15000",          denoised_seed     ]     subprocess.run(cmd_denoise, check=True, capture_output=True)          # 重新识别引导词 (降噪后识别会更准)     model = whisper.load_model("base")     res = model.transcribe(denoised_seed)     new_text = res['text'].strip()          # 立即进行对比生成     sys.path.append(r"E:\VideoTranslator_Project")     from clone_dubber import VideoCloneDubber     db = VideoCloneDubber()          test_text = "这是消噪后的种子测试，让我们听听起手和收尾是否还有残留杂音。"     print("  -> 正在使用【消噪基因】生成对比样本...")     wav = db.model.generate(text=test_text, prompt_wav_path=denoised_seed, prompt_text=new_text)          out_p = r"E:\VideoTranslator_Project\output_final\DENOISED_GEN_VERIFY_SPK00.wav"     sf.write(out_p, wav, db.sample_rate)          # 更新库记录     role_lib['SPEAKER_00']['wav'] = denoised_seed     role_lib['SPEAKER_00']['text'] = new_text     with open(role_lib_path, "w") as f: json.dump(role_lib, f, indent=2)          print(f"\n🏆 消噪验证样本已产出：{out_p}")  if __name__ == "__main__":     denoise_and_test_seed()
